select jsonb_build_object(
 'tables',coalesce((select jsonb_agg(jsonb_build_object(
  'name',c.relname,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
  'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid,true)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
  'constraints',coalesce((select jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid,true)) order by k.conname) from pg_constraint k where k.conrelid=c.oid),'[]'::jsonb),
  'indexes',coalesce((select jsonb_agg(pg_get_indexdef(i.indexrelid) order by ic.relname) from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=c.oid),'[]'::jsonb),
  'policies',coalesce((select jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname) from pg_policy p where p.polrelid=c.oid),'[]'::jsonb),
  'anonAnyData',has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),
  'authenticatedAnyData',has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),
  'serviceSelect',has_table_privilege('service_role',c.oid,'SELECT'),'serviceInsert',has_table_privilege('service_role',c.oid,'INSERT'),'serviceUpdate',has_table_privilege('service_role',c.oid,'UPDATE'),'serviceDelete',has_table_privilege('service_role',c.oid,'DELETE'),'serviceTruncate',has_table_privilege('service_role',c.oid,'TRUNCATE'),'serviceReferences',has_table_privilege('service_role',c.oid,'REFERENCES'),'serviceTrigger',has_table_privilege('service_role',c.oid,'TRIGGER')
 ) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('analytics_experiments','analytics_experiment_assignments')),'[]'::jsonb),
 'functions',coalesce((select jsonb_agg(jsonb_build_object('name',p.proname,'signature',p.oid::regprocedure::text,'securityDefiner',p.prosecdef,'config',p.proconfig,'language',l.lanname,'sourceSha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'definitionSha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'owner',pg_get_userbyid(p.proowner),'ownerSuperuser',(select r.rolsuper from pg_roles r where r.oid=p.proowner),'ownerBypassRls',(select r.rolbypassrls from pg_roles r where r.oid=p.proowner),'anonExecute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticatedExecute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'serviceExecute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by p.proname,p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('analytics_experiment_manage','analytics_experiment_assign','analytics_experiment_expose','analytics_experiment_outcome','analytics_experiment_results','analytics_experiment_count_exclusion','analytics_experiment_withdraw_consent','analytics_experiment_purge')),'[]'::jsonb),
 'triggers',coalesce((select jsonb_agg(jsonb_build_object('name',t.tgname,'table',t.tgrelid::regclass::text,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) order by t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and (c.relname in ('analytics_experiments','analytics_experiment_assignments') or (c.relname='consent_records' and t.tgname='analytics_experiment_withdraw_consent'))),'[]'::jsonb)
) as catalog
